import csv, collections, re
id2sym={}; id2desc={}
with open('refs/human.refseq.rna.fna') as f:
    for line in f:
        if line.startswith('>'):
            header=line[1:].strip(); rid=header.split()[0]
            # take last parenthesized token before the RNA type phrase; this is the official symbol in RefSeq titles
            before=re.split(r', (?:transcript variant|mRNA|long non-coding RNA|non-coding RNA|microRNA|small nucleolar RNA|small nuclear RNA|ribosomal RNA)', header)[0]
            ms=re.findall(r'\\((["'^()]+)'"\\)', before)
            sym=ms[-1] if ms else 'NA'
            id2sym[rid]=sym; id2desc[rid]=header

def read(fn):
    d={}
    with open(fn) as f:
        for row in csv.DictReader(f,delimiter='\\t'):
            d[row['Name']]={'tpm':float(row['TPM']),'reads':float(row['NumReads'])}
    return d
A=read('salmon_A_refseq.tsv'); B=read('salmon_B_refseq.tsv')
g=collections.defaultdict(list)
for rid in set(A)|set(B):
    sym=id2sym.get(rid, 'NA')
    ar=A.get(rid,{}).get('reads',0); br=B.get(rid,{}).get('reads',0)
    at=A.get(rid,{}).get('tpm',0); bt=B.get(rid,{}).get('tpm',0)
    if ar+br>0: g[sym].append((rid,ar,br,at,bt,id2desc.get(rid,'')))
rows=[]
for sym, vals in g.items():
    expr=[v for v in vals if v[1]+v[2]>=1]
    ta=sum(v[1] for v in expr); tb=sum(v[2] for v in expr)
    if len(expr)<2 or min(ta,tb)<10: continue
    l1=sum(abs(v[1]/ta-v[2]/tb) for v in expr)
    rows.append((l1, min(ta,tb), ta+tb, abs(ta-tb)/(ta+tb), sym, expr))
rows.sort(key=lambda x:(-x[0], -x[1]))
for l1,mint,total,imb,sym,expr in rows[:50]:
    print(f'{sym}\\ttotal={total:.1f}\\tmin={mint:.1f}\\timb={imb:.3f}\\tL1={l1:.3f}\\tn={len(expr)}')
    for rid,ar,br,at,bt,desc in sorted(expr, key=lambda v:-(v[1]+v[2]))[:5]: print(f'  {rid}\\t{ar:.1f}\\t{br:.1f}\\t{desc[:110]}')
PY"

